(()=>{'use strict';const G=window.LingxiEngine,$=id=>document.getElementById(id),KEY=G.KEY;const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state=null,tab='events',skillOpen=false;const openActionGroups=new Set(['urgent','practice','encounters','spar']);
try{const raw=JSON.parse(localStorage.getItem(KEY));state=G.migrate(raw);if(state&&raw.version!==state.version)localStorage.setItem(KEY,JSON.stringify(state));}catch(_){}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(_){}}
function choiceCards(map,name){return Object.entries(map).map(([id,v],i)=>`<label class="select-card"><input type="radio" name="${name}" value="${id}" ${i===0?'checked':''}><span><b>${esc(v.name)}</b><small>${esc(v.text)}</small></span></label>`).join('');}
const rarityTone={基础:'basic',凡品:'common',灵品:'spirit',仙品:'immortal'};
function rarityBadge(rarity){return rarity&&rarityTone[rarity]?`<span class="rarity rarity-${rarityTone[rarity]}" title="品阶以适用境界为准">${esc(rarity)}</span>`:'';}
function relicValue(item){return item?`<span class="relic-value"><span class="relic-name">${esc(item.name)}</span>${rarityBadge(item.rarity)}</span>`:'未得';}
function aspectText(value){const a=value||{};return `${(a.elements||[]).map(v=>G.ELEMENTS[v]).filter(Boolean).join('、')||'素元'} · ${G.POLARITIES[a.polarity]||'冲和'}`;}
function aspectTag(value){return `<span class="affinity-tag">${esc(aspectText(value))}</span>`;}
function affinityLevels(s){const p=G.points(s);return `<div class="affinity-levels"><h3>五行亲和</h3><div>${['wood','fire','earth','metal','water','plain'].map(k=>`<span>${k==='plain'?'素元（最低）':G.ELEMENTS[k]} <b>${p[k]||0}</b></span>`).join('')}</div><h3>阴阳气象</h3><div>${['yin','yang','harmony'].map(k=>`<span>${G.POLARITIES[k]}${k==='harmony'?'（较低）':''} <b>${p[k]||0}</b></span>`).join('')}</div><p>素元为五行最低值，冲和为阴阳较低值；达到派生值时各分项自然已达标。战斗中可随敌人择相克之气，但收益受最低值限制。</p></div>`;}
function statusAffinity(s){const p=G.points(s),keys=['wood','fire','earth','metal','water'],pts=keys.map((k,i)=>{const a=(Math.PI*2*i/5)-Math.PI/2,r=39,v=Math.max(0,Math.min(6,p[k]||0))/6;return {label:G.ELEMENTS[k],key:k,value:p[k]||0,x:50+Math.cos(a)*r,y:48+Math.sin(a)*r,dx:50+Math.cos(a)*(r*v),dy:48+Math.sin(a)*(r*v),lx:50+Math.cos(a)*40,ly:48+Math.sin(a)*40};});const poly=a=>a.map(q=>`${q.x.toFixed(1)},${q.y.toFixed(1)}`).join(' '),yin=Math.max(0,Math.min(6,p.yin||0)),yang=Math.max(0,Math.min(6,p.yang||0)),total=yin+yang||1,share=yin/total*100;return `<div class="status-affinity-heading">五行 · 阴阳 <small>亲和 / 6</small></div><div class="affinity-visual"><svg class="affinity-radar" viewBox="0 0 100 100" role="img" aria-label="五行亲和：${pts.map(q=>`${q.label} ${q.value}`).join('，')}">${[2,4,6].map(n=>`<polygon points="${poly(pts.map(q=>({x:50+(q.x-50)*n/6,y:48+(q.y-48)*n/6})))}" class="radar-grid"/>`).join('')}<polygon points="${poly(pts.map(q=>({x:q.dx,y:q.dy})))}" class="radar-area"/>${pts.map(q=>`<circle cx="${q.dx}" cy="${q.dy}" r="1.8" class="radar-dot affinity-${q.key}"/>`).join('')}${pts.map(q=>`<text x="${q.lx}" y="${q.ly}" class="radar-label">${q.label} ${q.value}</text>`).join('')}</svg></div><div class="polarity-visual" role="img" aria-label="阴 ${yin}，阳 ${yang}"><span>阴 <b>${yin}</b></span><div class="polarity-bar"><i style="width:${share}%"></i></div><span>阳 <b>${yang}</b></span></div><div class="derived-affinity">素元 ${p.plain} · 冲和 ${p.harmony}</div>`;}
const urgentActions=new Set(['stage','attempt']);
const practiceActions=new Set(['secludeYear','cultivate','manual','rest']);
const tradeActions=new Set(['sellall','buymax','buygrain','sellherb','buymanual','heal','buyelixir','bodyTonic']);
function actionGroupId(id){if(urgentActions.has(id))return 'urgent';if(id.startsWith('spar-'))return 'spar';if(id.startsWith('kit-'))return 'kit';if(id.startsWith('learn-'))return 'learn';if(practiceActions.has(id))return 'practice';if(tradeActions.has(id))return 'trade';return 'encounters';}
const actionGroupNames={urgent:'眼前关隘',encounters:'人物与机缘',practice:'修行与起居',trade:'坊市与补给',learn:'习招',spar:'演武切磋',kit:'借用试器'};
function actionButton(a){return `<button type="button" class="action ${a.id==='attempt'?'main-action':''}" data-command="action:${esc(a.id)}" ${a.disabled?'disabled':''}><strong>${rarityBadge(a.rarity)}${esc(a.label)}</strong><small>${esc(a.detail)}</small></button>`;}
function actionGroups(actions){if(!actions.length)return '';const groups=new Map();for(const a of actions){const group=actionGroupId(a.id);if(!groups.has(group))groups.set(group,[]);groups.get(group).push(a);}return ['urgent','encounters','practice','trade','learn','spar','kit'].filter(k=>groups.has(k)).map(k=>{const items=groups.get(k),open=k==='urgent'||openActionGroups.has(k);return `<details class="action-group" data-action-group="${k}" ${open?'open':''}><summary>${actionGroupNames[k]} <span>${items.length} 项</span></summary><div class="action-group-items">${items.map(actionButton).join('')}</div></details>`;}).join('');}
function gateText(s,item){const req={基础:0,凡品:2,灵品:3,仙品:4}[item.rarity]||0;if(!req)return '';const missing=G.affinityMissing(s,item),elements=item.elements||[];return `<p class="affinity-note">亲和门槛：${elements.length?elements.map(k=>G.ELEMENTS[k]).join('／')+' ≥'+req+(elements.length>1?'（择一）':''):'五行不限'}${item.polarity&&item.polarity!=='harmony'?'；'+G.POLARITIES[item.polarity]+' ≥'+req:''}${missing.length?' · 尚缺 '+esc(missing.join('、')):' · 已契合'}</p>`;}
function advantageLine(offense,defense){const m=G.matchup(offense,defense),atk=Math.round((m.attackFactor-1)*100),guard=Math.round((m.defenseFactor-1)*100);return `实际攻击 ${atk>=0?'+':''}${atk}% · 对方护体 ${guard>=0?'+':''}${guard}%`;}
function drawCreation(){$('creation').hidden=!!state;$('game').hidden=!state;if(state)return;$('origins').innerHTML=choiceCards(G.ORIGINS,'origin');$('talents').innerHTML=choiceCards(G.TALENTS,'talent');}
const sceneDescription={templeLamp:'夜里灯火将尽，书案上还有半页模糊的蚀文。',templeLedger:'观中粮册的数目对不上，有弟子急着下山取粮。',cliffDebate:'两名同门在岩畔为一段行气之说争论不休。',cliffWind:'风吹散了石刻旁的浮土，一行旧字露了出来。',mountainHerbs:'药径旁新生的灵草扎在松软山土里。',mountainMist:'浓雾忽起，山路通向一条不熟悉的捷径。',marketGrain:'坊市粮价忽有波动，商户正核对账目。',marketTome:'旧书摊上一卷拓本无人识得，摊主请你帮忙。',templeMeridian:'你已凝元显意，同门请你辨一段逆行的气机。',cliffPulse:'岩下灵息有了形状，你能读出它的流向。',mountainVein:'后山地脉微动，药株和行气都与从前不同。',marketScript:'书商拿出完整拓本，想请已有元基的人辨真伪。',templeSeal:'观中旧印与元基相合，能用来封合冲关留下的裂隙。',cliffFormation:'山岩上的残阵开始回应你的元息。',mountainCave:'灵泉流入深洞，足以疗伤，也藏着稀有灵草。',marketPact:'一位行脚修士拿出冲关旧注，与商人争论价钱。',templeBreath:'元成入真后，你可以收束真息疗伤，也可以将它贯入元脉。',cliffVision:'云上脉象清晰可辨，同行弟子等你作出判断。',mountainSpring:'深山泉畔，灵材与泉气彼此牵引。',marketExchange:'临近开脉，山下商会愿换你手中的灵材和资粮。'};
const sceneTitle={templeLamp:'善渊观 · 青灯残字',templeLedger:'善渊观 · 粮册疑点',cliffDebate:'千丈岩 · 辩经',cliffWind:'千丈岩 · 风口石刻',mountainHerbs:'苍梧后山 · 药苗',mountainMist:'苍梧后山 · 迷雾',marketGrain:'山下集市 · 粮价',marketTome:'山下集市 · 旧拓本',templeMeridian:'凝元 · 理气',cliffPulse:'凝元 · 岩中灵息',mountainVein:'凝元 · 新药脉',marketScript:'凝元 · 完整拓本',templeSeal:'淬元 · 旧印封脉',cliffFormation:'淬元 · 岩上残阵',mountainCave:'淬元 · 深洞灵泉',marketPact:'淬元 · 冲关注解',templeBreath:'入真 · 收束真息',cliffVision:'入真 · 云上脉象',mountainSpring:'入真 · 泉畔灵材',marketExchange:'入真 · 商会交易'};
const title={seclusion:'闭关修行',scroll:'同门来问',herbalist:'山路上的采药人',yeFollowup:'药径旧事',guFollowup:'顾闻溪邀你校卷',guReturn:'顾闻溪的回信',chengFollowup:'程上师的差事',chengReturn:'旧卷有了下文',guText:'星篆残篇',guFinish:'校成真章',yeText:'泉脉药径',yeFinish:'青华试法',luMeet:'陆知衡的护卷契',luReturn:'履约与归卷',sealAudience:'照骨玄泉池契',stoneScout:'山中石髓泉眼',mentor:'程上师的书案',trueText:'上师的密卷',spring:'择玉液华池',manual:'转修功法',stage:'筑元关隘',attempt:'此生只此一关'};
const description={seclusion:'选定最多闭关多久。每月照常耗粮、修炼或静养；在后山还会采药补给。遇事件、筑元关口、断粮风险或寿元危险立即出关。',scroll:'顾闻溪带来一卷难解的道书，请你当众释义。你怎样处理其中的关键一页？',herbalist:'叶青蘅跌伤在药径旁。她识得后山隐泉，却急需一株灵草疗伤。',yeFollowup:'几个月后，你又经过这条药径。叶青蘅记得当时的选择，泉径与眼前的生计都可以再作打算。',guFollowup:'顾闻溪记得你如何处理那页残卷，邀你再辨一部旧书。',guReturn:'先前校卷或送稿的选择，换来了不同的后续。',chengFollowup:'整理旧卷之后，程上师想请你再帮一次忙。',chengReturn:'程上师记得你接过的差事，向你问起下一步。',guText:'星篆残篇有缺页。可与顾闻溪合校，也可购卷独解；此时只是立题，不会直接得法。',guFinish:'寻回缺页、养足根骨之后，试行星篆真章。若未备齐，可先离开继续准备。',yeText:'叶青蘅留下养脉纲目，你可以帮她养护泉脉，也可独自取样；两路都需采药验证。',yeFinish:'亲自采药并将身体养到能承法，才可试行青华篇。',luMeet:'陆知衡不轻售真章。你可以押资立契、替商队护送散卷、出手拦截截卷修士，或暂不介入。若交手失利，卷册受损后仍可赔付修复，继续这条人物线。',luReturn:'护卷之约将到期。可以用银钱或灵草结清，亦可卖掉手中散卷，离开这条路线。',sealAudience:'守池差事或护卷凭证可换池契。持契仍须备药，才可在善渊观取用照骨玄泉。',stoneScout:'遇见寻泉客闻秋后，可让泉、出银钱、独自探访或争夺本次优先权。胜出只降低石髓池入池所需的灵草，不会直接取得仙品华池。',mentor:'上师放下道书，看你是来求教、帮忙，还是求取更深的法门。',trueText:'你已修习导脉经多时，又替上师整理过道书。程上师取出一卷未署名的密卷，问你是否愿为他校订。',spring:'开脉用池各有代价。后山可寻瑶光或石髓池；善渊观持池契可取照骨玄泉。',manual:'已得的功法可以随时切换，不消耗月份；本层功行上限与修炼速度会随当前功法改变。',stage:'稳固根基更慢但更稳；急进省时，却更易失利并留下暗伤。失败损失四分之一的本层功行，并留下元基裂隙；重试有降品风险，可以消耗灵草修补。',attempt:'法门、华池、根基都已备下。强求更容易冲出高品，也更容易大幅掉档，且开脉成功率更低。'};
const afterStories={
 gu:['顾闻溪的信夹在星篆残页里，纸边满是改过又划掉的字。她找到一处旧注的误读：照那一句行气，后学也许会伤到元基。你的校本已经借出，错字里也有你的笔迹。\n\n“我会把自己的名字写在勘误后面，”她说，“你的那一行，你打算怎么办？”','半年后，顾闻溪又来了一封信。校本传到了山下，读书人开始争论当时是谁先读错了那一行。她没有替你作答，只把两份旧注和一页新纸放在案上。'],
 ye:['一张沾了药汁的笺纸送到后山。叶青蘅写字很急，开头只有“药还缺两株”，末尾却仔细记了伤者的脉象。她自己背着药篓来了，见你先看药方，才抬眼问你。\n\n“这人等不得。不过你也正在养脉，别答应了又怪自己。”','数月过去，叶青蘅再见你时先看了一眼你的气色。她说起那条山径的人，随后从药篓里取出一只纸包。上回留下的选择，这一次要由你自己收尾。'],
 lu:['陆知衡送来的不是催债帖，而是一册账。你求得真章后，护卷的旧契已经结清；商队却又找出一页散在外面的余卷。他把卷目与两笔价钱摆在桌上，手指压住最末一行。\n\n“契结了，人情没结。我不替你决定这页纸该走哪条路。”','陆知衡的回信写在旧契背面，没有一句寒暄。他记清了上次的银钱、余卷和收卷人，也留下一笔账等你来定。见面时他才说：“先把事讲明，再谈交情。”'],
 cheng:['程上师在书案前翻你校过的旧卷，未立即谈真章。他指了指廊下几个初来善渊观的弟子：有人连第一口气也行不稳。\n\n“我传你法，不等于你欠我一生差事，”他说，“只是他们现在也在门外。你愿意教一程，还是取了酬劳去过自己的关？”','过了些时日，程上师又取出你当年的行气注。廊下弟子已有的各自入了门，有的仍在原处打转。他把一张旧注推给你，没有问你是否后悔，只问你这次怎么看。']
};
function promptTitle(s){if(s.pending==='luReturn'&&s.story.luRoute==='fightDelayed')return '陆知衡 · 修复受损散卷';if(s.pending?.startsWith('after-')){const [,who,part]=s.pending.split('-');return ({gu:'顾闻溪 · 星篆误字',ye:'叶青蘅 · 山中药笺',lu:'陆知衡 · 契外余卷',cheng:'程上师 · 传法之后'})[who]+(part==='2'?' · 回音':'');}return s.pending?.startsWith('scene-')?sceneTitle[s.pending.slice(6)]:title[s.pending];}
function promptDescription(s){if(s.pending==='luReturn'&&s.story.luRoute==='fightDelayed')return '护卷交手失利后，陆知衡带卷脱身，但散卷缺页。赔付银钱或灵草可以修复卷册，契约延期后仍能继续；也可卖出残卷，离开这条路。';if(s.pending?.startsWith('after-')){const [,who,part]=s.pending.split('-');return afterStories[who][Number(part)-1];}return s.pending?.startsWith('scene-')?`${sceneDescription[s.pending.slice(6)]||'山中有事发生。'}刚才的行动已经耗时一月；选择不会再耗月。`:description[s.pending];}
const intentText={strike:'试探出手 · 下一招为普通攻击',charge:'沉肩蓄势 · 本合不攻击，下合重击',burst:'蓄力重击 · 伤害更高',guard:'守住中门 · 本合护体提高',flow:'引气贯锋 · 将耗内息进招',earthWard:'磐岩镇脉 · 将护身并反击',metalFlash:'霜锋掠影 · 剑招迅疾',vinePounce:'藤影扑击 · 天赋神通将发',paperCut:'裂页断章 · 短刃直取卷册'};
function combatArtAspect(art,fallback){return art?.elements?.length||art?.polarity?art:fallback||{};}
function combatArtClass(art,fallback){const aspect=combatArtAspect(art,fallback),elements=(aspect.elements||[]).filter(k=>G.ELEMENTS[k]);return `combat-art ${elements.length===1?'combat-element-'+elements[0]:'combat-element-plain'} ${aspect.polarity==='yin'?'combat-yin':aspect.polarity==='yang'?'combat-yang':'combat-harmony'}`;}
function combatArtLabel(art,fallback){return aspectText(combatArtAspect(art,fallback));}
function combatLine(line,playerAspect,enemyAspect){return esc(line).replace(/(你以「[^」]+」|对方施展(?:天赋神通|招式)「[^」]+」|对方以「(?:寻常出手|蓄力重击)」)/g,part=>{const player=part.startsWith('你'),name=part.match(/「([^」]+)」/)?.[1],arts=player?G.TECHNIQUES:G.FOE_ARTS,art=Object.values(arts).find(a=>a.name===name);return `<span class="${combatArtClass(art,player?playerAspect:enemyAspect)}">${part}</span>`;}).replace(/(你的气血\s*−\s*\d+|对方气血\s*−\s*\d+|削去气血\s*\d+|你回生气血\s*\d+|对方回生气血\s*\d+)/g,part=>{const healing=part.includes('回生'),player=part.startsWith('你的')||part.startsWith('你回生');return `<strong class="combat-change ${healing?'combat-heal':'combat-damage'}-${player?'player':'enemy'}">${part}</strong>`;});}
function sparFighter(name,person){return `<div class="spar-fighter"><strong>${esc(name)}</strong><div class="spar-measure">气血 <b>${person.currentQi} / ${person.qi}</b></div><div class="spar-bar"><span style="width:${Math.max(0,Math.round(person.currentQi/person.qi*100))}%"></span></div><div class="spar-measure">内息 <b>${person.currentNei} / ${person.nei}</b></div><div class="spar-bar inner"><span style="width:${Math.max(0,Math.round(person.currentNei/person.nei*100))}%"></span></div><small>攻势 ${person.attack} · 护体 ${person.defense}<br>闪避 ${person.evasion} · 生机 ${person.vitality||0} · 反制 ${person.counter||0}<br>出手 ${aspectTag(person.attackAspect||person)}<br>护身 ${aspectTag(person.defenseAspect||person)}${person.gear?`<br>器物 ${esc(Object.values(person.gear).join("、"))}`:""}${person.innate?`<br>天赋 ${esc(person.innate)}`:""}</small></div>`;}
function sparPanel(s){if(s.combat){const c=s.combat;return `<span class="eyebrow">${c.storyEncounter==='luEscort'?'坊市护卷':c.storyEncounter==='springContest'?'后山争泉':c.storyEncounter==='mountainApe'?'药径遭遇':c.storyEncounter?'主线交锋':'演武切磋'} · 第 ${c.round} 合</span><h2>${esc(c.enemy.name)}</h2><div class="spar-fighters">${sparFighter(s.name,c.player)}${sparFighter(c.enemy.name,c.enemy)}</div><p class="affinity-note">你攻击对方：${esc(advantageLine(c.player.attackAspect,c.enemy))}<br>对方攻击你：${esc(advantageLine(c.enemy,c.player.defenseAspect))}</p><p class="spar-intent"><b>对手动向</b> ${G.FOE_ARTS[c.intent]?`<span class="${combatArtClass(G.FOE_ARTS[c.intent],c.enemy)}">${esc(intentText[c.intent])} · ${esc(combatArtLabel(G.FOE_ARTS[c.intent],c.enemy))}</span>`:esc(intentText[c.intent]||'正在观察你')}</p><div class="spar-actions">${G.combatOptions(s).filter(o=>!G.TECHNIQUES[o.id]).map(o=>`<button type="button" data-command="combat:${esc(o.id)}" ${o.disabled?'disabled':''}><strong>${esc(o.label)}</strong><small>${esc(o.detail)}</small></button>`).join('')}</div>${G.combatOptions(s).some(o=>G.TECHNIQUES[o.id])?`<details class="tech-menu" ${skillOpen?'open':''}><summary>施展招式 · ${G.combatOptions(s).filter(o=>G.TECHNIQUES[o.id]).length} 门</summary><div class="spar-actions">${G.combatOptions(s).filter(o=>G.TECHNIQUES[o.id]).map(o=>`<button type="button" data-command="combat:${esc(o.id)}" ${o.disabled?'disabled':''}><strong class="${combatArtClass(G.TECHNIQUES[o.id],c.player.attackAspect)}">${esc(o.label)}</strong><small>${esc(combatArtLabel(G.TECHNIQUES[o.id],c.player.attackAspect))} · ${esc(o.detail)}</small></button>`).join('')}</div></details>`:''}<div class="auto-choices"><span>${c.storyEncounter?'应对方式':'一键切磋'}</span><button type="button" data-command="combat:auto-aggressive">猛攻 · 优先出招</button><button type="button" data-command="combat:auto-steady">稳扎稳打 · 留意来招</button></div><div class="spar-history" role="log" aria-live="polite">${c.history.slice(-5).map(line=>`<p>${combatLine(line,c.player.attackAspect,c.enemy)}</p>`).join('')}</div><p class="spar-footnote">${c.storyEncounter==='luEscort'?'此战关系到陆知衡的卷册与契约，失手或撤退后仍可设法补救。':c.storyEncounter==='springContest'?'争胜只影响这次优先探查权；失手或收手后，其他泉径仍可寻找。':c.storyEncounter==='mountainApe'?'药径交手关系到采集与伤势，认输可退回药径。':c.storyEncounter?'此战会影响人物关系与后续机缘，认输可结束交锋。' :'练武坪点到即止。正式切磋结束后以一月结算调息、复盘与印证；不留暗伤，每场气血和内息重新结算。'}</p>`;}
 const p=G.combatStats(s),r=s.sparRecord?.last,kit=s.trainingGear||{},record=s.sparRecord||{};
 if(r?.storyEncounter)return `<span class="eyebrow">主线交锋 · 战斗结束</span><h2>${esc(r.opponent)} · <span class="spar-result ${r.result==='胜出'?'spar-win':r.result==='失手'?'spar-loss':'spar-other'}">${esc(r.result)}</span></h2><p class="spar-intro">自动与手动交锋使用同一套逐回合结算。战报默认收起，需要时可展开复盘。</p><details class="story-battle-report"><summary>查看战报 · ${r.rounds} 合</summary><div class="spar-history full-history">${r.history.map(line=>`<p>${combatLine(line,r.playerAspect,r.enemyAspect)}</p>`).join('')}</div></details>`;
 return `<span class="eyebrow">演武坪 · 入场前</span><h2>先看自身，再选对手</h2><p class="spar-intro">五行分别增强生机、攻势、护体、反制与闪避；阴增内息，阳增气血。正式切磋连同调息、复盘与后续印证按一月结算；不留暗伤。每名常驻对手首次战胜另有一次性奖励。</p><div class="spar-preview"><strong>你当前的身手 · ${esc(G.ITEMS.manual[s.manual].name)}</strong><p>气血 ${p.qi} · 内息 ${p.nei} · 攻势 ${p.attack} · 护体 ${p.defense} · 闪避 ${p.evasion} · 生机 ${p.vitality} · 反制 ${p.counter}</p><p class="affinity-note">出手 ${aspectTag(p.attackAspect)} · 护身 ${aspectTag(p.defenseAspect)}</p><small>借用：${esc([kit.staff?'试锋木杖':null,kit.vest?'护心藤甲':null,kit.shoes?'逐风履':null,kit.talisman?'试法铜符':null].filter(Boolean).join('、')||'无')}。入场内息随当前心神而定。</small></div><p class="spar-tally"><strong>总战绩</strong>　${(record.wins||0)+(record.losses||0)+(record.draws||0)+(record.withdrawals||0)} 战 · ${record.wins||0} 胜 · ${record.losses||0} 负 · ${record.draws||0} 平 · ${record.withdrawals||0} 次收手</p>${r?`<div class="spar-last"><span class="eyebrow">最近一战</span><h3>${esc(r.opponent)} · <span class="spar-result ${r.result==='胜出'?'spar-win':r.result==='失手'?'spar-loss':'spar-other'}">${esc(r.result)}</span></h3><details class="story-battle-report"><summary>展开战报 · ${r.rounds} 合</summary><div class="spar-history full-history">${(r.history||[]).map(line=>`<p>${combatLine(line,r.playerAspect,r.enemyAspect)}</p>`).join('')}</div></details></div>`:''}`;
}
const people={gu:{name:'顾闻溪',place:'千丈岩',role:'校卷同门',portrait:'gu',line:'一字之误，可能叫后来人多走几十年弯路。',memory:s=>s.story?.guText==='complete'?'她与你走过星篆校勘一程。':s.story?.guRoute?'她记得你们共读旧卷的那日。':'她记得初识时那页蚀文是如何处理的。'},ye:{name:'叶青蘅',place:'苍梧后山',role:'采药人',portrait:'ye',line:'药总是不够，但人也不能因为这个就不救。',memory:s=>s.story?.yeRoute==='trade'?'她记得你索酬指路，此后仍肯按规矩交易。':s.story?.yeRoute==='leave'?'她记得你绕过药径，往后各凭本事。':s.story?.yeRoute?'她记得那株分给她的药。':'你在后山与她相识。'},cheng:{name:'程上师',place:'善渊观',role:'下院上师',portrait:'cheng',line:'法不可轻传。你先说说自己读懂了什么。',memory:s=>s.story?.trueTextReady?'他已认可你的校卷之功。':s.flags.mentor?'他记得你替他整理过旧卷。':'你到书案前请教过他。'},lu:{name:'陆知衡',place:'山下集市',role:'护卷商人',portrait:'lu',line:'契书有价，答应过的事也有价。',memory:s=>s.story?.luCredential?'你们之间的护卷契已经结清。':s.story?.luBattle==='won'?'你曾在后巷替他护住散卷，他记得这份信任。':s.story?.luBattle==='lost'?'护卷失手后，你补偿修卷，仍继续履约。':s.story?.luBattle==='retreated'?'你从后巷撤退后，他仍愿意让你修复遗失的卷页。':s.story?.luRoute?'他记得你们签下的旧约。':'你们曾在集市谈过护卷。'},wen:{name:'闻秋',place:'苍梧后山',role:'寻泉客',portrait:'wen',line:'泉脉无主，先看见的人也未必守得住。',memory:s=>s.story?.stonePriority?'你们曾为石髓池的先探之权交涉或交手，他记得那次结果。':s.story?.stoneClue?'他曾与你分享或交易过石髓池的泉脉线索。':'你在后山泉径与他相识。'}};
const gearLabels={weapon:'兵器',armor:'护身',shoes:'足履',relic:'佩器'};
function bookHeading(kind,name){return `<div class="codex-title"><span class="eyebrow">${kind}</span><h2>${name}</h2></div>`;}
function realmLabel(item){return item.stageMax==null?'不限境界（无额外战斗加成）':`${G.STAGES[item.stageMin]}至${G.STAGES[item.stageMax]}（开脉前）`;}
function realmBadge(item){return `<span class="realm-badge">${item.stageMax==null?'不限境界':'开脉前适用'}</span>`;}
function equipped(s){const g=s.trainingGear||{};return {weapon:G.EQUIPMENT.weapon[g.staff?1:0],armor:G.EQUIPMENT.armor[g.vest?1:0],shoes:G.EQUIPMENT.shoes[g.shoes?1:0],relic:G.EQUIPMENT.relic[g.talisman?1:0]};}
function profile(s){const b=G.combatStats(s),eq=equipped(s),remaining=Math.max(0,s.lifeLimitMonths-s.ageMonths);return `<div class="portrait-hero"><img src="./images/seeker-${s.gender==='male'?'male':'female'}.webp" alt="${esc(s.name)}的水墨画像"><div><span class="eyebrow">苍梧人物小传</span><h2>${esc(s.name)}</h2><p>${s.gender==='male'?'男':'女'} · ${esc(G.ORIGINS[s.origin].name)} · ${esc(G.TALENTS[s.talent].name)}</p><p>${esc(G.STAGES[s.stage])} · ${esc(G.LOCATIONS[s.location].name)}</p></div></div>${affinityLevels(s)}<div class="catalog-grid"><section class="catalog-card"><h3>五维与修行</h3><dl>${[['五行本源',(s.elements||[]).map(v=>G.ELEMENTS[v]).join('、')||'素元'],['阴阳气象',G.POLARITIES[s.polarity]||'冲和'],['根骨',s.root],['悟性',s.wit],['体魄',`${G.effectiveBody(s)} / ${s.body}`],['道心',s.dao],['处世',s.social],['心神',s.focus],['蚀文心得',s.insight],['本层功行',`${s.progress.toFixed(2)} / ${G.cap(s)}`],['累计功行',s.totalProgress.toFixed(2)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section><section class="catalog-card"><h3>岁月与身手</h3><dl>${[['年龄',`${(s.ageMonths/12).toFixed(1)} 岁`],['寿限',`${(s.lifeLimitMonths/12).toFixed(1)} 岁`],['余寿',`${(remaining/12).toFixed(1)} 年`],['暗伤',s.wounds],['元基裂隙',s.foundationStrain||0],['出手属性',aspectText(b.attackAspect)],['护身属性',aspectText(b.defenseAspect)],['气血',b.qi],['内息',b.nei],['火 · 攻势',b.attack],['土 · 护体',b.defense],['水 · 闪避',b.evasion],['木 · 生机',b.vitality],['金 · 反制',b.counter]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section><section class="catalog-card"><h3>功法与招式</h3><p>现修 ${relicValue(G.ITEMS.manual[s.manual])} ${aspectTag(G.ITEMS.manual[s.manual])} · 华池 ${s.spring?relicValue(G.ITEMS.spring[s.spring]):'未定'}</p><p>所学功法：${s.manuals.map(i=>esc(G.ITEMS.manual[i].name)).join('、')}</p><p>所学招式：${(s.knownTechniques||[]).map(id=>`${esc(G.TECHNIQUES[id]?.name||id)}（${esc(G.techniqueProgress(s,id).name)}）`).join('、')||'尚未学会；演武坪可试学'}</p><p>元基：${s.foundationGrades.map((n,i)=>`${i+1}关${['','下','中','上'][n]}品`).join('、')||'尚未筑元'}</p></section><section class="catalog-card"><h3>随身器物</h3><dl>${Object.entries(eq).map(([slot,item])=>`<div><dt>${gearLabels[slot]}</dt><dd>${esc(item.name)} ${rarityBadge(item.rarity)} ${realmBadge(item)} ${aspectTag(item)}</dd></div>`).join('')}</dl><p class="small-print">演武坪借用的器物离坪后不能再用于切磋；本章主线尚未开放战斗掉落。</p></section><section class="catalog-card"><h3>资粮与往来</h3><p>银钱 ${s.silver} · 口粮 ${s.grain} · 灵草 ${s.herbs}</p><p>${Object.entries(people).filter(([id])=>s.codex?.people?.includes(id)).map(([id,p])=>`${p.name} ${s.npcFavor[id]>=0?'+':''}${s.npcFavor[id]}`).join(' · ')||'还未结识书册中的人物'}</p></section></div>`;}
function peopleBook(s){const ids=s.codex?.people||[];return bookHeading('人物志','苍梧故人')+(ids.length?ids.filter(id=>people[id]).map(id=>{const p=people[id];return `<article class="catalog-person"><div class="npc-portrait ${p.portrait}" role="img" aria-label="${p.name}画像"></div><div><span class="eyebrow">${p.role} · ${p.place}</span><h2>${p.name} <small>往来 ${s.npcFavor[id]>=0?'+':''}${s.npcFavor[id]}</small></h2><p>“${p.line}”</p><p>${esc(p.memory(s))}</p></div></article>`}).join(''):'<div class="no-books">尚未结识人物。相逢之后，这一卷才会写下他们的姓名和旧事。</div>');}
function beastsBook(s){const ids=s.codex?.combatants||[],gearNames={weapon:'兵器',armor:'护具',shoes:'鞋履',relic:'佩器'};return bookHeading('交手见闻','山泽异闻')+(ids.length?ids.map(id=>{const foe=G.SPAR_OPPONENTS[id],record=s.codex?.combatantNotes?.[id]||{kind:foe?.kind||'human',seenArts:[],seenGear:[]};if(!foe)return '';const beast=record.kind==='beast',realm=beast?'未开脉':foe.rank==='入门'?'入门吐纳':foe.rank;const arts=(record.seenArts||[]).map(art=>G.FOE_ARTS[art]).filter(Boolean),gear=(record.seenGear||[]).map(slot=>foe.gear?.[slot]?`${gearNames[slot]||slot}：${foe.gear[slot]}`:'').filter(Boolean);return `<article class="catalog-card"><span class="eyebrow">${beast?'妖兽':'人'} · ${esc(foe.rank==='山中异兽'?'苍梧山':'苍梧演武坪')}</span><h2>${esc(foe.name)}</h2><p>境界：${esc(realm)}${beast?' · 威胁：山中异兽':` · 威胁：${esc(realm)}修士`}</p><p>${beast?'异兽习性仍待进一步查明。':'此人修行与来历尚待进一步查明。'}</p>${record.observations?.length?`<p>交手见闻：${record.observations.map(esc).join('；')}</p>`:''}${arts.length?`<p>${arts.map(art=>`${art.innate?'天赋神通':'已见招式'}：${esc(art.name)}（${esc(G.proficiencyName?G.proficiencyName(foe.artRanks?.[Object.keys(G.FOE_ARTS).find(key=>G.FOE_ARTS[key]===art)]||0):'已见')}）`).join('；')}</p>`:'<p>尚未见其施展招式或神通。</p>'}${gear.length?`<p>已见装备：${gear.map(esc).join('、')}</p>`:'<p>尚未辨明装备。</p>'}</article>`}).join(''):'<div class="no-books">尚未与人类修士或山中异兽交手。遇见之后，见闻才会逐渐补全。</div>');}
const attributeNames={root:'根骨',wit:'悟性',body:'体魄',dao:'道心'};
const manualNotes=['观中入门法，吐纳缓慢；久修可增益悟性。','青篆行气温养根骨。','导脉淬炼根骨，也磨砺道心。','太微真章洗炼形神，实修有益体魄与寿限。','星篆推演蚀文，实修增益悟性与心得。','青华法借灵草养脉，兼顾体魄、伤势与寿限。','行云法以气脉参照人脉，实修增益处世。'];
const manualGrowth=['久修亦可磨炼悟性；亲和成长按当前实际门槛结算。','偏重木行与自身阴阳气象；根骨另随长期实修成长。','偏重水、阴；根骨与道心另随长期实修成长。','偏重金、阳；长期实修亦能锻炼体魄并延寿。','偏重火、阴；长期推演亦能增长悟性，悟性圆满后转为心得。','偏重木、火、阳；配合灵草可温养体魄、暗伤与寿元。','偏重土、金与自身阴阳气象；长期实修亦能磨炼处世。'];
function artsBook(s){const manuals=[...new Set(s.manuals||[0])].map(i=>[i,G.ITEMS.manual[i]]).filter(([,item])=>item);
 const techniques=(s.knownTechniques||[]).map(id=>G.TECHNIQUES[id]).filter(Boolean);
 return `<div class="arts-book">${bookHeading('功法与招式','玄门法鉴')}<span class="eyebrow">已习法门</span><h2>功法</h2>${manuals.map(([i,item])=>`<article class="catalog-card"><h3>${rarityBadge(item.rarity)}${esc(item.name)} ${aspectTag(item)}${s.manual===i?' · 现修':''}</h3><p class="manual-realm"><strong>适用境界</strong> ${esc(G.STAGES[item.stageMin])}至${esc(G.STAGES[item.stageMax])}（开脉前）</p>${gateText(s,item)}<p>承法门槛：${Object.entries(item.requirements).map(([k,v])=>`${attributeNames[k]||k} ${v}`).join('、')||'无额外属性门槛'}</p><p>${esc(manualNotes[i]||'既得之法，仍须亲自修习。')}</p><p class="manual-growth"><strong>实修成长</strong> ${esc(i===0?'素元吐纳会同时磨炼五行与阴阳，但亲和越高越难精进。':manualGrowth[i]||'实修会逐步塑造自身根基。')} 当前亲和进度 ${s.affinityTraining?.[i]||0} / ${G.affinityTrainingNeed(s,i)}，再实修 ${Math.max(0,G.affinityTrainingNeed(s,i)-(s.affinityTraining?.[i]||0))} 次触发下一次对应亲和成长。</p><p>每月修行功行约 +${G.cultivationGain({...s,manual:i}).toFixed(2)} · 本层功行上限 ${G.cap(s,i)}${i===s.manual?' · 当前已修习':''}</p></article>`).join('')}<span class="eyebrow">所学招式</span><h2>招式与神通</h2>${techniques.length?techniques.map(t=>`<article class="catalog-card"><h3>${esc(t.name)} ${t.elements?aspectTag(t):'<span class="affinity-tag">随出手属性</span>'}</h3>${gateText(s,t)}<p class="affinity-note">${G.techniqueMissing(s,Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t)).length?'当前不可施展：'+esc(G.techniqueMissing(s,Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t)).join('、')):'当前功法、兵器与亲和契合'}</p><p>${(()=>{const id=Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t),p=G.techniqueProgress(s,id),rank=p.name==='精通'?2:p.name==='熟稔'?1:0,e=G.techniqueEffect(id,rank);return `当前效果：内息 ${e.cost}${id==='interrupt'?` · 伤害 ${e.mult.toFixed(2)}× · 截断 ${Math.round(e.interruptChance*100)}%`:` · 伤害 ${e.mult.toFixed(2)}×${id==='surge'?` · 命中 ${e.hit}`:''}`}。${esc(G.STAGES[t.stage])}起可在切磋中施展。`;})()}</p><p class="technique-progress"><strong>熟练度 · ${esc(G.techniqueProgress(s,Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t)).name)}</strong>　实战 ${G.techniqueProgress(s,Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t)).count}${G.techniqueProgress(s,Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t)).next?` / ${G.techniqueProgress(s,Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t)).next} · 还需 ${G.techniqueProgress(s,Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t)).next-G.techniqueProgress(s,Object.keys(G.TECHNIQUES).find(id=>G.TECHNIQUES[id]===t)).count} 次升档`:' · 当前阶段已圆满'}</p></article>`).join(''):'<div class="no-books">尚未学会招式。演武坪可习得入门行气技。</div>'}</div>`;}
function elixirBook(s){const item=G.ITEMS.elixir;if(!s.codex?.elixirs?.includes(item.id))return bookHeading('丹药录','丹霞拾遗')+'<div class="no-books">尚未见过丹药。游历时若见到丹药，此卷便会记下。</div>';
 return bookHeading('丹药录','丹霞拾遗')+`<p class="catalog-caption">品阶依适用境界而定，并不代表此丹在更高境界仍有相同效力。</p><article class="catalog-card"><span class="eyebrow">丹药 · 山下集市见闻</span><h2>${rarityBadge(item.rarity)}${esc(item.name)} ${realmBadge(item)}</h2><p class="manual-realm"><strong>适用境界</strong> ${esc(realmLabel(item))}</p><p>坊市售价 10 两。服后接下来 6 次实际吐纳所得功行 +25%；药效不可叠加，耗尽后可再次购买，不耗月份。${s.elixirBoost?`当前余效 ${s.elixirBoost} 次。`:''}</p><p>${s.elixirBoost?`药效正在运转，还余 ${s.elixirBoost} 次吐纳。`:s.flags.elixir?'你曾服用过此丹；药效已尽，可以再次购买。':'见过即可记入丹药录，无须购买。'}</p></article>`;}
function equipmentBook(s){const defaults=new Set(['bare','robe','cloth','none',...(s.codex?.gear||[])]);return bookHeading('器物录','百器谱')+'<p class="catalog-caption">品阶按开脉前衡量，跨境界的器物另定效力。</p>'+Object.entries(G.EQUIPMENT).map(([slot,items])=>`<section class="catalog-card"><h3>${gearLabels[slot]}</h3>${items.filter(item=>defaults.has(item.id)).map(item=>`<p>${rarityBadge(item.rarity)}<strong>${esc(item.name)}</strong> ${realmBadge(item)} ${aspectTag(item)} · ${esc(item.effect)}</p>${gateText(s,item)}<p class="manual-realm"><strong>适用境界</strong> ${esc(realmLabel(item))}</p>`).join('')}</section>`).join('');}
function draw(){drawCreation();if(!state)return;const s=state,remain=Math.max(0,s.lifeLimitMonths-s.ageMonths),chapterRemain=Math.max(0,30*12-s.ageMonths),limit=G.cap(s),loc=G.LOCATIONS[s.location]||G.LOCATIONS.temple;
 $('status-affinity').innerHTML=statusAffinity(s);
 $('character-name').textContent=s.name;$('identity').textContent=`${G.ORIGINS[s.origin]?.name||'求道者'} · ${G.TALENTS[s.talent]?.name||'凡心'}`;$('root').textContent=s.root;$('wit').textContent=s.wit;$('body').textContent=G.effectiveBody(s)===s.body?String(s.body):`${G.effectiveBody(s)}（原 ${s.body}）`;$('dao').textContent=s.dao;$('social').textContent=s.social;$('wit-study').textContent=s.wit>=8?'悟性已至上限':`研经提升悟性：${s.studyWork} / ${G.studyNeed(s.wit)}`;$('date').textContent=G.time(s.month);$('stage').textContent=G.STAGES[s.stage];$('progress').textContent=`${Math.min(s.progress,limit).toFixed(2)} / ${limit}`;$('progress-bar').style.width=`${Math.min(100,s.progress/limit*100)}%`;$('total-progress').textContent=s.totalProgress.toFixed(2);
 $('lifespan').textContent=`约余 ${(remain/12).toFixed(1)} 年`;$('ages').textContent=`${(s.ageMonths/12).toFixed(1)} / ${(s.lifeLimitMonths/12).toFixed(1)} 岁`;$('chapter-deadline').textContent=chapterRemain?`三十岁前开脉 · 余 ${Math.floor(chapterRemain/12)} 年 ${chapterRemain%12} 月`:'三十岁期限已至';$('chapter-deadline').classList.toggle('urgent-deadline',chapterRemain<=24);$('life-bar').style.width=`${Math.max(0,remain/s.lifeLimitMonths*100)}%`;
 for(const k of ['silver','grain','herbs','focus','wounds','insight'])$(k).textContent=s[k];$('foundation-strain').textContent=s.foundationStrain||0;$('manual').innerHTML=relicValue(G.ITEMS.manual[s.manual]);$('spring').innerHTML=s.spring?relicValue(G.ITEMS.spring[s.spring]):'未定';$('foundation').textContent=`${s.foundation} / 3`;$('foundation-grades').textContent=s.foundationGrades.length?s.foundationGrades.map((g,i)=>`${i+1}关${['','下','中','上'][g]}`).join(' · '):'尚未筑元';const met=(s.codex?.people||[]).filter(id=>people[id]);$('relations-block').hidden=met.length===0;$('relations-list').innerHTML=met.map(id=>`<div><span>${esc(people[id].name)}</span><b>${s.npcFavor[id]>0?'+':''}${s.npcFavor[id]}</b></div>`).join('');
 $('scene-title').textContent=s.ending?'本章已终':loc.name;$('scene-detail').textContent=s.ending?'翻阅此生的卷册，或重新开始。':loc.text;$('book-count').textContent=s.books.length?`· ${s.books.length}`:'';
 $('ending').hidden=!s.ending;if(s.ending){const label=s.ending.kind==='success'?'第一章 · 开脉':s.ending.kind==='mortal'?'凡人结局':'身死道消';$('ending').innerHTML=`<span class="eyebrow">${label}</span><h2>${s.ending.kind==='success'?esc(s.ending.grade)+'脉象':'道途终止'}</h2><p>${esc(s.ending.body)}</p><div class="life-summary"><h3>此生总录</h3><ul>${G.lifeSummary(s).map(line=>`<li>${esc(line)}</li>`).join('')}</ul></div><button type="button" id="ending-book" class="ghost">翻阅此生卷册</button>`;}
 $('event-prompt').hidden=!s.pending;if(s.pending){$('event-prompt').innerHTML=`<span class="eyebrow">此刻的抉择</span><h2>${esc(promptTitle(s)||'抉择')}</h2><p>${esc(promptDescription(s)||'')}</p><div class="prompt-options">${G.options(s).map(o=>`<button type="button" data-command="choice:${esc(o.id)}" ${o.disabled?'disabled':''}><strong>${rarityBadge(o.rarity)}${esc(o.label)}</strong>${o.detail?`<small>${esc(o.detail)}</small>`:''}</button>`).join('')}</div>`;}
 $('combat-panel').hidden=!(s.combat||s.location==='arena');if(!$('combat-panel').hidden)$('combat-panel').innerHTML=sparPanel(s);
 $('log').innerHTML=s.logs.filter(e=>!e.batch).slice(-60).reverse().map(e=>`<article class="entry ${['突破','结局','开脉','闭关','采药'].includes(e.tag)?'important':''}"><span>${esc(G.time(e.month))} · ${esc(e.tag)}</span><p>${esc(e.text)}</p>${e.effect?`<small>${esc(e.effect)}</small>`:''}</article>`).join('');
 $('action-heading').textContent=s.combat?'演武交锋':s.pending?'先作抉择':s.ending?'这一生已落卷':'本月何为';$('action-list').innerHTML=actionGroups(G.available(s))||`<p class="empty-action">${s.combat?'先在战局中选一招；可随时收手。':s.ending?'卷册仍可翻阅':s.pending?'眼前的选择尚未作出':'暂无可用行动'}</p>`;
 $('travel-current').textContent=`· 当前 ${loc.name}`;$('travel-list').innerHTML=Object.entries(G.LOCATIONS).map(([id,v])=>`<button type="button" data-command="travel:${id}" ${s.pending||s.combat||s.ending||s.location===id?'disabled':''}>${esc(v.name)}</button>`).join('');
 $('profile-content').innerHTML=profile(s);$('people-content').innerHTML=peopleBook(s);$('beasts-content').innerHTML=beastsBook(s);$('equipment-content').innerHTML=equipmentBook(s);$('arts-content').innerHTML=artsBook(s);$('elixirs-content').innerHTML=elixirBook(s);
 $('books-content').innerHTML=bookHeading('一年一卷 · 生平纪事','岁华纪')+(s.ending?`<article class="book life-summary"><span class="eyebrow">终卷 · 生平总录</span><h2>${esc(s.name)}的一生</h2><ul>${G.lifeSummary(s).map(line=>`<li>${esc(line)}</li>`).join('')}</ul></article>`:'')+(s.books.length?s.books.map(b=>`<article class="book"><span class="eyebrow">求道第 ${b.year} 年 · ${esc(b.stage)} · ${b.age} 岁</span><h2>${esc(b.title===`第${b.year}卷 · 苍梧岁月`?`第${b.year}卷 · 山中岁华`:b.title)}</h2><ul>${b.lines.map(line=>`<li>${esc(line)}</li>`).join('')}</ul></article>`).join(''):'<div class="no-books">第一年尚未过去。年终会将这一年的重要经历装订成卷。</div>');
 showTab();}
function showTab(){for(const id of ['events','profile','people','beasts','equipment','arts','elixirs','books']){const pane=$(id==='events'?'story-content':`${id}-content`),button=$(`tab-${id}`),selected=tab===id;pane.hidden=!selected;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));}}
$('create-form').addEventListener('change',e=>{if(e.target.name!=='elements')return;const boxes=[...document.querySelectorAll('input[name="elements"]')],plain=boxes.find(b=>b.value==='plain');if(e.target===plain&&plain.checked)boxes.forEach(b=>{if(b!==plain)b.checked=false;});else if(e.target.checked)plain.checked=false;const selected=boxes.filter(b=>b.checked).map(b=>b.value);if(!G.compatibleElements(selected)){e.target.checked=false;$('affinity-help').textContent='这几行互相克制，不能同修；请选择不相克的组合。';}else $('affinity-help').textContent='单行初始 3、双行各 2；素元开局五行各 1。素元是五行最低值。';if(!boxes.some(b=>b.checked))plain.checked=true;});
$('create-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);state=G.create({name:d.get('name'),origin:d.get('origin'),talent:d.get('talent'),gender:d.get('gender'),elements:d.getAll('elements'),polarity:d.get('polarity')});save();draw();});
document.addEventListener('toggle',e=>{if(e.target.matches?.('.tech-menu'))skillOpen=e.target.open;if(e.target.matches?.('.action-group')){const key=e.target.dataset.actionGroup;if(e.target.open)openActionGroups.add(key);else openActionGroups.delete(key);}},true);document.addEventListener('click',e=>{const b=e.target.closest('[data-command]');if(b&&!b.disabled&&state){const hadPending=!!state.pending,command=b.dataset.command;state=G.step(state,command);const shouldJump=command.startsWith('action:')&&!hadPending&&!!state.pending;save();draw();if(shouldJump)requestAnimationFrame(()=>$('event-prompt')?.scrollIntoView({behavior:'smooth',block:'start'}));}if(e.target.id==='ending-book'){tab='books';showTab();}});
for(const id of ['events','profile','people','beasts','equipment','arts','elixirs','books'])$(`tab-${id}`).addEventListener('click',()=>{tab=id;showTab();});
const statusDetails=$('status-details');if(statusDetails&&window.matchMedia('(max-width:700px)').matches)statusDetails.open=false;
$('restart').addEventListener('click',()=>$('restart-dialog').showModal());$('restart-dialog').addEventListener('close',()=>{if($('restart-dialog').returnValue==='confirm'){state=null;localStorage.removeItem(KEY);tab='events';draw();}});
draw();})();
